function GraphLaplacian(V, E):
    L <- zero matrix |V| x |V|
    for (i,j) in E:
        L[i][j] -= 1; L[j][i] -= 1
        L[i][i] += 1; L[j][j] += 1
    return L

function TropicalRank(M):
    for k = n down to 1:
        for each k x k submatrix M':
            if TropicallyNonsingular(M'):
                return k
    return 0

function TropicallyNonsingular(M):
    min_val <- +inf, count <- 0
    for each permutation s of [n]:
        val <- sum_i M[i][s(i)]
        if val < min_val: min_val <- val, count <- 1
        elif val == min_val: count += 1
    return count == 1
